jQuery(document).ready(function($){function loadFomoMessage(){const delay=Math.floor(Math.random()*9000)+4000;setTimeout(()=>{$.ajax({url:fomo_ajax.url,type:"GET",data:{action:"gamipress_social_proof_fomo_send_message_AJAX"},dataType:"json",success:function(data){if(data.message){const container=$("#message-container");container.empty();container.append(data.message);const box=container.find(".fomo-message");box.removeClass("show");setTimeout(()=>{box.addClass("show");}, 50);setTimeout(()=>{box.removeClass("show");},4000);}}});},delay);}loadFomoMessage();setInterval(loadFomoMessage,8000);});